"use client";

import { useEffect, useState } from "react";
import { useParams, useRouter } from "next/navigation";
import { useFormik } from "formik";
import axiosInstance from "@/utils/axiosInstance";
import { FiTrash, FiUploadCloud } from "react-icons/fi";
import { toast } from "react-toastify";

const ProductDraftForm = () => {
  const params = useParams();
  const productId = params?.productId as string;
  const router = useRouter();

  const [productData, setProductData] = useState(null);
  const [isSubmitting, setSubmitting] = useState(false);

  const fetchProductsData = async () => {
    try {
      const response = await axiosInstance.get(`/products/${productId}`);
      setProductData(response.data);
    } catch (error) {
      console.error("Error fetching product data:", error);
    }
  };

  const fetchPictures = async () => {
    try {
      const response = await axiosInstance.get(`/pictures/${productId}`);
      console.log("Fetched pictures:", response.data);

      if (response.data.success) {
        const updatedPictures = response.data.data.length
          ? response.data.data.map((pic) => pic.productPictureUrl)
          : [null, null, null]; // Set default values if no pictures

        // Only update the state if the pictures have changed
        if (JSON.stringify(updatedPictures) !== JSON.stringify(formik.values.productPictures)) {
          formik.setFieldValue("productPictures", updatedPictures);
        }
      } else {
        console.error("Failed to fetch pictures:", response.data.message);
        formik.setFieldValue("productPictures", [null, null, null]); // Ensure empty array if no pictures found
      }
    } catch (error) {
      console.error("Error fetching pictures:", error);
    }
  };

  useEffect(() => {
    if (productId && !productData) {
      console.log("Fetching product data for ID:", productId);
      fetchProductsData();
    }
  }, [productId, productData]); // Only fetch product data once

  useEffect(() => {
    if (productData && !productData.pictures) {
      console.log("Fetching pictures for product...");
      fetchPictures(); // Fetch pictures after product data is available
    }
  }, [productData]); // Only fetch pictures once productData is available

  const handleUploadPicture = async (position: number) => {
    const input = document.createElement("input");
    input.type = "file";
    input.accept = "image/*";
    input.click();

    input.onchange = async (event) => {
      const file = (event.target as HTMLInputElement).files?.[0];
      if (!file) return;

      try {
        setSubmitting(true);
        const formData = new FormData();
        formData.append("file", file);
        await axiosInstance.post(`/pictures/${productId}/${position}/upload`, formData, {
          headers: {
            "Content-Type": "multipart/form-data",
          },
        });
        toast.success("Picture uploaded successfully!");
        fetchPictures(); // Fetch pictures after uploading
      } catch (error) {
        toast.error("Failed to upload picture");
      } finally {
        setSubmitting(false);
      }
    };
  };

  const handleDeletePicture = async (position: number) => {
    try {
      setSubmitting(true);
      await axiosInstance.delete(`/pictures/${productId}/${position}/delete`);
      toast.success("Picture deleted successfully!");
      fetchPictures(); // Fetch pictures after deleting
    } catch (error) {
      toast.error("Error deleting picture");
    } finally {
      setSubmitting(false);
    }
  };

  return (
    <div className="p-6 bg-white shadow-md rounded-lg">
      <h2 className="text-3xl font-semibold mb-4">📝 Edit Draft Product</h2>

      <form className="space-y-4">
        {/* Product Pictures */}
        <div>
          <label className="block text-gray-700 font-semibold">Product Pictures</label>
          <div className="flex flex-wrap gap-2 md:flex-nowrap">
            {formik.values.productPictures.map((pic, position) => (
              <div key={position} className="relative w-24 h-24 border rounded flex items-center justify-center bg-gray-100">
                {pic ? (
                  <>
                    <img
                      src={pic}
                      alt={`Product ${position + 1}`}
                      className="w-full h-full object-cover rounded"
                    />
                    <button
                      type="button"
                      className={`absolute top-1 right-1 p-1 text-white rounded-full transition ${
                        isSubmitting ? "bg-red-400 cursor-not-allowed" : "bg-red-600 hover:bg-red-700"
                      }`}
                      onClick={() => handleDeletePicture(position + 1)}
                      disabled={isSubmitting}
                    >
                      <FiTrash className="w-5 h-5" />
                    </button>
                  </>
                ) : (
                  <button
                    type="button"
                    className={`absolute top-1 right-1 p-1 text-gray-700 rounded-full transition ${
                      isSubmitting ? "bg-gray-300 cursor-not-allowed" : "bg-gray-300 hover:bg-gray-400"
                    }`}
                    onClick={() => handleUploadPicture(position + 1)}
                    disabled={isSubmitting}
                  >
                    <FiUploadCloud className="w-6 h-6" />
                  </button>
                )}
              </div>
            ))}
          </div>
        </div>
      </form>
    </div>
  );
};

export default ProductDraftForm;
